#ifndef NUMUTILS_H
#define NUMUTILS_H

double num_mean(const double values[], int n);
double num_dot(const double a[], const double b[], int n);

#endif

#include "numutils.h"

double num_mean(const double values[], int n) {
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
        sum += values[i];
    }
    return sum / n;
}

double num_dot(const double a[], const double b[], int n) {
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
        sum += a[i] * b[i];
    }
    return sum;
}

#include <stdio.h>
#include "numutils.h"

int main(void) {
    double a[] = {1.0, 2.0, 3.0, 4.0};
    double b[] = {2.0, 0.0, 1.0, 3.0};
    int n = 4;

    printf("Mean of a: %.2f\n", num_mean(a, n));
    printf("Dot product: %.2f\n", num_dot(a, b, n));
    return 0;
}
